import networkx as nx
from collections import deque

SOURCE = object()  # object node

def is_plan_fail(exc=None):
    return False

class PlanFailure(Exception): pass

# ---------- raw deficient cut ----------
def find_deficient_cut(n, links, participants, roots, p, env):
    """links list (u,v); env dict link->rate. Return sorted physical vertex cut or None."""
    D = sum(roots.values())
    G = nx.DiGraph()
    G.add_nodes_from(range(n))
    G.add_node(SOURCE)
    for vid,(u,v) in enumerate(links):
        c = p * env.get(vid, 0)
        if c > 0:
            # aggregate just in case
            if G.has_edge(u,v): G[u][v]['capacity'] += c
            else: G.add_edge(u,v, capacity=c)
            if G.has_edge(v,u): G[v][u]['capacity'] += c
            else: G.add_edge(v,u, capacity=c)
    for v in sorted(participants):
        r = roots[v]
        if G.has_edge(SOURCE,v): G[SOURCE][v]['capacity'] += r
        else: G.add_edge(SOURCE,v,capacity=r)
    P = set(participants)
    for sink in sorted(P):
        val, part = nx.minimum_cut(G, SOURCE, sink)
        if val < D:
            S = {x for x in part if x is not SOURCE}
            # verify with physical links
            outcap = 0
            for vid,(u,v) in enumerate(links):
                if ((u in S) != (v in S)):
                    outcap += p * env.get(vid, 0)
            R = sum(roots[v] for v in P if v in S)
            if 0 < R < D and outcap < R and (sink not in S):
                return sorted(S)
    return None

# ---------- switch elimination ----------
def remove_switches(n, links, participants, roots, p, env):
    C = set(participants)
    D = sum(roots.values())
    fg = nx.DiGraph()
    fg.add_nodes_from(range(n))
    fg.add_node(SOURCE)
    for vid,(u,v) in enumerate(links):
        c = p * env.get(vid, 0)
        if c <= 0: continue
        if fg.has_edge(u,v): fg[u][v]['capacity'] += c
        else: fg.add_edge(u,v,capacity=c)
        if fg.has_edge(v,u): fg[v][u]['capacity'] += c
        else: fg.add_edge(v,u,capacity=c)
    for v in sorted(C):
        r = roots[v]
        if r > 0: fg.add_edge(SOURCE,v,capacity=r)
    edge_map = {}
    switches = sorted(v for v in range(n) if v not in C)
    for w in switches:
        for u in sorted(list(fg.predecessors(w))):
            if not fg.has_edge(u,w): continue
            # u should never be SOURCE
            assert u is not SOURCE
            assert fg[u][w].get('capacity',0) > 0
            for t in sorted(list(fg.successors(w))):
                if not fg.has_edge(w,t): continue
                assert fg[w][t].get('capacity',0) > 0
                M = min(fg[u][w]['capacity'], fg[w][t]['capacity'])
                # temporary edge u -> SOURCE; ensure no existing
                assert not fg.has_edge(u,SOURCE)
                fg.add_edge(u,SOURCE)
                cpct_ut = fg[u][t]['capacity'] if fg.has_edge(u,t) else 0
                if cpct_ut == 0:
                    if fg.has_edge(u,t): del fg[u][t]['capacity']
                    else: fg.add_edge(u,t)
                else:
                    del fg[u][t]['capacity']
                for v in sorted(C):
                    if v == u or v == t: continue
                    cpct_vw = fg[v][w]['capacity'] if fg.has_edge(v,w) else 0
                    if cpct_vw == 0:
                        if fg.has_edge(v,w): del fg[v][w]['capacity']
                        else: fg.add_edge(v,w)
                    else:
                        del fg[v][w]['capacity']
                    fval = nx.maximum_flow_value(fg,u,w) - D
                    if fval < M: M = fval
                    if cpct_vw == 0: fg.remove_edge(v,w)
                    else: fg[v][w]['capacity'] = cpct_vw
                    if M == 0: break
                fg.remove_edge(u,SOURCE)
                if M > 0:
                    assert not fg.has_edge(w,SOURCE)
                    fg.add_edge(w,SOURCE)
                    for v in sorted(C):
                        if v != u:
                            cpct_vt = fg[v][t]['capacity'] if fg.has_edge(v,t) else 0
                            if cpct_vt == 0:
                                if fg.has_edge(v,t): del fg[v][t]['capacity']
                                else: fg.add_edge(v,t)
                            else:
                                del fg[v][t]['capacity']
                            fval = nx.maximum_flow_value(fg,w,t) - D
                            if cpct_vt == 0: fg.remove_edge(v,t)
                            else: fg[v][t]['capacity'] = cpct_vt
                        else:
                            fval = nx.maximum_flow_value(fg,w,t) - D
                        if fval < M: M = fval
                        if M == 0: break
                    fg.remove_edge(w,SOURCE)
                if cpct_ut == 0:
                    if fg.has_edge(u,t): fg.remove_edge(u,t)
                else:
                    fg[u][t]['capacity'] = cpct_ut
                if M <= 0: continue
                if (u,t) not in edge_map: edge_map[u,t] = {}
                if w not in edge_map[u,t]: edge_map[u,t][w] = 0
                edge_map[u,t][w] += M
                fg[u][w]['capacity'] -= M
                fg[w][t]['capacity'] -= M
                if fg.has_edge(u,t): fg[u][t]['capacity'] += M
                elif u != t: fg.add_edge(u,t,capacity=M)
                if fg[w][t].get('capacity',0) == 0: fg.remove_edge(w,t)
                if fg[u][w].get('capacity',0) == 0: break
            if fg.has_edge(u,w):
                assert fg[u][w].get('capacity',0) == 0, ('residual incoming',w,u,fg[u][w])
                fg.remove_edge(u,w)
        # switch should now be isolated
        if fg.has_edge(w,SOURCE) or fg.has_edge(SOURCE,w):
            raise PlanFailure('source adjacency left')
        for x in list(fg.predecessors(w)):
            if fg.has_edge(x,w): raise PlanFailure(('switch pred left',w,x))
        for x in list(fg.successors(w)):
            if fg.has_edge(w,x): raise PlanFailure(('switch succ left',w,x))
    H = nx.DiGraph()
    H.add_nodes_from(sorted(C))
    for a,b,d in fg.edges(data=True):
        if a is SOURCE or b is SOURCE: continue
        if a not in C or b not in C: continue
        c = d.get('capacity',0)
        if c > 0:
            if H.has_edge(a,b): H[a][b]['capacity'] += c
            else: H.add_edge(a,b,capacity=c)
    # verify source-to-sink flows in H if possible
    for v in sorted(C):
        g2 = nx.DiGraph(H); g2.add_node(SOURCE)
        for u in sorted(C):
            if roots[u] > 0: g2.add_edge(SOURCE,u,capacity=roots[u])
        if nx.maximum_flow_value(g2,SOURCE,v) < D:
            raise PlanFailure(('H flow lost',v))
    # clean edge_map positive only
    em2 = {}
    for (a,b),d in edge_map.items():
        if a not in C or b not in C: continue
        dd = {w:c for w,c in d.items() if c>0}
        if dd: em2[(a,b)] = dd
    return H, em2

# ---------- branching generator ----------
class _Gen:
    def __init__(self, H, participants, roots):
        self.allnodes = set(participants)
        self.roots = {u:c for u,c in roots.items() if c>0}
        self.flow_graph = nx.DiGraph(H)
        self.s_nodes = {}
        self.Tcount = {}
        self.Ts = {}
        self.Vs = {}
        self.Cs = {}
        for idx,u in enumerate(sorted(self.roots)):
            s = ('SOURCE',u,0)
            self.s_nodes[(u,0)] = s
            self.flow_graph.add_node(s)
            self.flow_graph.add_edge(s,u)
            self.Tcount[u] = 1
            self.Ts[(u,0)] = []
            self.Vs[(u,0)] = {u}
            self.Cs[(u,0)] = self.roots[u]
        self.num = sum(self.roots.values())
    def new_tree(self, root, edges, nodes, num):
        idx = self.Tcount[root]; self.Tcount[root] += 1
        s = ('SOURCE',root,idx)
        self.s_nodes[(root,idx)] = s
        self.flow_graph.add_node(s)
        for v in sorted(nodes): self.flow_graph.add_edge(s,v)
        self.Ts[(root,idx)] = list(edges)
        self.Vs[(root,idx)] = set(nodes)
        self.Cs[(root,idx)] = num
        return (root,idx)
    def test_edge(self,w,j,x,y):
        csum = 0
        for (u,i),s in list(self.s_nodes.items()):
            if (u,i) == (w,j): continue
            c = self.Cs[u,i]
            if c <= 0: continue
            assert not self.flow_graph.has_edge(x,s)
            self.flow_graph.add_edge(x,s,capacity=c)
            csum += c
        assert self.Cs[w,j] > 0
        assert self.flow_graph.has_edge(x,y)
        capxy = self.flow_graph[x][y].get('capacity',0)
        val = nx.maximum_flow_value(self.flow_graph,x,y)
        chunks = min(self.Cs[w,j], capxy, val - csum)
        for (u,i),s in list(self.s_nodes.items()):
            if (u,i) == (w,j): continue
            if self.flow_graph.has_edge(x,s): self.flow_graph.remove_edge(x,s)
        return max(0,chunks)
    def generate(self):
        q = deque(sorted(self.s_nodes.keys()))
        while q:
            w,j = q.popleft()
            s_node = self.s_nodes[(w,j)]
            bfs = deque(sorted(self.Vs[(w,j)]))
            while bfs:
                x = bfs.popleft()
                succs = sorted(y for y in self.flow_graph.successors(x) if y not in self.s_nodes.values())
                for y in succs:
                    if y not in self.allnodes or y in self.Vs[(w,j)]: continue
                    if not self.flow_graph.has_edge(x,y): continue
                    if self.flow_graph[x][y].get('capacity',0) <= 0: continue
                    chunks = self.test_edge(w,j,x,y)
                    if chunks <= 0: continue
                    bfs.append(y)
                    if chunks < self.Cs[(w,j)]:
                        nk = self.new_tree(w,self.Ts[(w,j)],self.Vs[(w,j)],self.Cs[(w,j)]-chunks)
                        self.Cs[(w,j)] = chunks
                        q.append(nk)
                    self.Ts[(w,j)].append((x,y))
                    self.Vs[(w,j)].add(y)
                    assert not self.flow_graph.has_edge(s_node,y)
                    self.flow_graph.add_edge(s_node,y)  # infinite capacity
                    self.flow_graph[x][y]['capacity'] -= chunks
                    if self.flow_graph[x][y]['capacity'] == 0:
                        self.flow_graph.remove_edge(x,y)
            if len(self.Vs[(w,j)]) != len(self.allnodes):
                raise PlanFailure(('partial tree',w,j,len(self.Vs[(w,j)]),len(self.allnodes)))
            if len(self.Ts[(w,j)]) != len(self.allnodes)-1:
                raise PlanFailure(('bad tree edge count',w,j))
            self.flow_graph.remove_node(self.s_nodes[(w,j)])
            del self.s_nodes[(w,j)]
            self.num -= self.Cs[(w,j)]
        if self.num != 0:
            raise PlanFailure(('remaining',self.num))
        # verify roots sum
        sums = {u:0 for u in self.roots}
        for (u,i),c in self.Cs.items(): sums[u]+=c
        for u,c in self.roots.items():
            if sums.get(u,0)!=c: raise PlanFailure(('root sum',u,sums.get(u,0),c))
        return dict(self.Ts), dict(self.Cs)

# ---------- recipe / route building ----------
def flat_edge_map(edge_map,u,t,c):
    # iterative recursion safe enough
    if (u,t) not in edge_map:
        return [[(u,t)]],[c]
    res_paths=[];res_cs=[]
    d=edge_map[(u,t)]
    for w,cp0 in sorted(d.items(), key=lambda e:e[1]):
        if c<=0: break
        cp = cp0
        if c >= cp:
            del d[w]
        else:
            d[w] -= c
            cp = c
        p1,c1 = flat_edge_map(edge_map,u,w,cp)
        p2,c2 = flat_edge_map(edge_map,w,t,cp)
        # match
        i=j=0
        while i<len(p1):
            x=min(c1[i],c2[j])
            if x>0:
                res_paths.append(p1[i]+p2[j]); res_cs.append(x)
            c1[i]-=x;c2[j]-=x
            if c1[i]==0:i+=1
            if c2[j]==0:j+=1
        c-=cp
    if c>0:
        res_paths.append([(u,t)]);res_cs.append(c)
        if (u,t) in edge_map: del edge_map[(u,t)]
    return res_paths,res_cs

def build_plan(H, em, participants, roots, n, links, p, env):
    participants=sorted(participants); P=set(participants); D=sum(roots.values())
    Ts,Cs=_Gen(H,participants,roots).generate()
    # merge identical whole tree records
    tree_acc={}
    for key,T in Ts.items():
        root=key[0]; cnt=Cs[key]
        if cnt<=0: continue
        ekey=tuple(sorted(T))
        if len(ekey)!=len(participants)-1 or len(set(ekey))!=len(ekey):
            raise PlanFailure(('tree shape',key,T))
        tree_acc[(root,ekey)]=tree_acc.get((root,ekey),0)+cnt
    tree_records=[]; L={}
    for (root,ekey),cnt in sorted(tree_acc.items()):
        tree_records.append([root,cnt,[[a,b] for a,b in ekey]])
        for e in ekey: L[e]=L.get(e,0)+cnt
    if len(tree_records)>8192: raise PlanFailure('too many trees')
    # root sums
    for v in participants:
        s=sum(cnt for (root,ekey),cnt in tree_acc.items() if root==v)
        if s!=roots[v]: raise PlanFailure(('root totals',v,s,roots[v]))
    if any(cnt<=0 or cnt>D for _,cnt,_ in tree_records): raise PlanFailure('tree count range')
    # link lookup
    edge_to_link={}
    for i,(u,v) in enumerate(links):
        edge_to_link[(u,v)]=(i,0)
        edge_to_link[(v,u)]=(i,1)
    recipes=[]
    atomic={}  # (link,dir)->id
    path_cache={}
    def atomic_id(e):
        if e not in edge_to_link: raise PlanFailure(('missing physical edge',e))
        l,d=edge_to_link[e]
        key=(l,d)
        if key not in atomic:
            atomic[key]=len(recipes); recipes.append([0,l,d])
        return atomic[key]
    def recipe_for_path(path):
        key=tuple(path)
        if key in path_cache: return path_cache[key]
        # build prefixes left to right
        first=path[0]
        rid=atomic_id(first)
        pref=(first,)
        for e2 in path[1:]:
            # join vertex is start of e2
            w=e2[0]
            if w in P: raise PlanFailure(('participant join',w,path))
            if pref in path_cache:
                rid=path_cache[pref]
            else:
                path_cache[pref]=rid
            aid=atomic_id(e2)
            nid=len(recipes)
            recipes.append([1,rid,aid])
            rid=nid
            pref=pref+(e2,)
        path_cache[key]=rid
        return rid
    em2={a:dict(d) for a,d in em.items()}
    routes=[]
    # include only ordered participant pairs with L positive
    for (u,v),cnt in sorted(L.items()):
        if cnt<=0: continue
        if u not in P or v not in P or u==v: raise PlanFailure(('bad L endpoint',u,v))
        paths,cs=flat_edge_map(em2,u,v,cnt)
        got=0
        for path,c in zip(paths,cs):
            if c<=0: continue
            got+=c
            if not path or path[0][0]!=u or path[-1][1]!=v:
                raise PlanFailure(('bad path endpoints',u,v,path))
            for i,(a,b) in enumerate(path):
                if i>0 and path[i-1][1]!=a: raise PlanFailure(('path break',path))
                if a==b: raise PlanFailure(('self edge',path))
            for z in range(1,len(path)):
                mid=path[z-1][1]
                if mid in P: raise PlanFailure(('participant transit',u,v,path,mid))
            rid=recipe_for_path(path)
            routes.append([u,v,c,rid])
            if len(routes)>32768: raise PlanFailure('too many routes')
        if got!=cnt: raise PlanFailure(('route sum',u,v,got,cnt))
    if len(recipes)>65536: raise PlanFailure('too many recipes')
    # Verifying aggregate recipe route counts equals L is structural by construction.
    return {'trees':tree_records,'routes':routes,'recipes':recipes}

def compile_plan(n, links, participants, roots, p, env):
    cut=find_deficient_cut(n,links,participants,roots,p,env)
    if cut is not None:
        return ('denied',cut)
    # Retry switch elimination order if needed.  Basic first.
    orders=[None]
    last=None
    for attempt in range(1):
        try:
            H,em=remove_switches(n,links,participants,roots,p,env)
            plan=build_plan(H,em,participants,roots,n,links,p,env)
            return ('prepared',plan)
        except PlanFailure as e:
            last=e
    raise last

# ---------- plan validator for testing ----------
